// AI-Personalized Pricing per Visitor
// Dynamically adjusts pricing based on visitor behavior, session data, and market conditions.

const express = require('express');
const router = express.Router();

// In-memory store for visitor profiles (replace with DB in production)
const visitorProfiles = new Map();

// Configuration
const BASE_PRICE = 100; // base price in cents
const MAX_DISCOUNT = 0.3; // max 30% discount
const PREMIUM_MULTIPLIER = 1.5; // premium multiplier for high-intent visitors

// Helper: compute personalized price
function computePrice(profile) {
  let price = BASE_PRICE;
  // Factor 1: session duration (longer = higher intent)
  if (profile.sessionDuration > 120) {
    price *= 1.2;
  } else if (profile.sessionDuration > 60) {
    price *= 1.1;
  }
  // Factor 2: page depth (more pages = more engaged)
  if (profile.pageDepth > 5) {
    price *= 1.15;
  } else if (profile.pageDepth > 3) {
    price *= 1.05;
  }
  // Factor 3: return visitor (loyalty discount)
  if (profile.returnVisitor) {
    price *= (1 - 0.1); // 10% discount
  }
  // Factor 4: cart abandonment (re-engagement discount)
  if (profile.abandonedCart) {
    price *= (1 - 0.15); // 15% discount
  }
  // Clamp to reasonable range
  price = Math.max(BASE_PRICE * (1 - MAX_DISCOUNT), Math.min(price, BASE_PRICE * PREMIUM_MULTIPLIER));
  return Math.round(price);
}

// POST /api/pricing/personalized
router.post('/personalized', (req, res) => {
  const { visitorId, sessionDuration, pageDepth, returnVisitor, abandonedCart } = req.body;
  if (!visitorId) {
    return res.status(400).json({ error: 'visitorId is required' });
  }
  // Update or create profile
  let profile = visitorProfiles.get(visitorId) || {};
  profile.sessionDuration = sessionDuration || profile.sessionDuration || 0;
  profile.pageDepth = pageDepth || profile.pageDepth || 0;
  profile.returnVisitor = returnVisitor !== undefined ? returnVisitor : (profile.returnVisitor || false);
  profile.abandonedCart = abandonedCart !== undefined ? abandonedCart : (profile.abandonedCart || false);
  visitorProfiles.set(visitorId, profile);

  const price = computePrice(profile);
  res.json({ visitorId, price, currency: 'USD' });
});

// GET /api/pricing/personalized/:visitorId
router.get('/personalized/:visitorId', (req, res) => {
  const profile = visitorProfiles.get(req.params.visitorId);
  if (!profile) {
    return res.status(404).json({ error: 'Visitor not found' });
  }
  const price = computePrice(profile);
  res.json({ visitorId: req.params.visitorId, price, currency: 'USD' });
});

module.exports = router;
